for (dx = -1; dx < 3; dx++) {
    for (dy = -1; dy < 3; dy++) {
        y = tileY + dy;
        if (tileX + dx >= 0 && tileX + dx <= 0x7f &&
            y >= 0 && y <= 0x3f &&
            LifeA[(tileX + dx) * 64 + y] != 0)
            count++;
    }
}
for (dx = -1; dx < 3; dx++) {
    for (dy = -1; dy < 3; dy++) {
        x = tileX + dx;
        y = tileY + dy;
        if (x >= 0 && x <= 0x7f && y >= 0 && y <= 0x3f &&
            LifeA[x * 64 + y] != 0)
            count++;
    }
}
for (dx = 0; dx < 4; dx++) {
    for (dy = 0; dy < 4; dy++) {
        y = tileY + dy - 1;
        if (tileX + dx - 1 >= 0 && tileX + dx - 1 <= 0x7f &&
            y >= 0 && y <= 0x3f &&
            LifeA[(tileX + dx - 1) * 64 + y] != 0)
            count++;
    }
}
for (dx = -1; dx < 3; dx++) {
    for (dy = -1; dy < 3; dy++) {
        y = tileY + dy;
        if (tileX + dx < 0 || tileX + dx > 0x7f ||
            y < 0 || y > 0x3f)
            continue;
        if (LifeA[(tileX + dx) * 64 + y] != 0)
            count++;
    }
}

